quickStart:
-- Hilbert-order rows by (lat, lon) when writing Parquet
COPY (
  SELECT * FROM source
  ORDER BY hilbert_encode([lat, lon]::DOUBLE[2])
) TO 'out.parquet' (FORMAT PARQUET);

-- Z-order (Morton) is faster but with weaker locality
COPY (
  SELECT * FROM source
  ORDER BY morton_encode([time, symbol_id]::INTEGER[2])
) TO 'out.parquet' (FORMAT PARQUET);
